sys_variable_value.value:
(function execute(inputs, outputs) {

    var caseRecord = inputs.visa_case_record;

    if (!caseRecord) {
        outputs.required_documents = 'No visa case found.';
        return;
    }

    // FIX: use case_type, not visa_category (visa_category is always null on the case record)
    var visaCategory = caseRecord.getValue('case_type');

    var requiredDocs = [];

    var gr = new GlideRecord('x_snc_visaguardi_0_document_configuration');
    gr.addQuery('visa_category', visaCategory);
    gr.addQuery('active', true);
    gr.addQuery('required', true);
    gr.orderBy('priority');
    gr.query();

    while (gr.next()) {
        // FIX: use getDisplayValue so this matches the format Step 4 uses for submitted documents
        requiredDocs.push(gr.getDisplayValue('document_type'));
    }

    if (requiredDocs.length === 0) {
        outputs.required_documents = 'No required documents configured for this visa category.';
    } else {
        outputs.required_documents = requiredDocs.join(', ');
    }

})(inputs, outputs);

