sys_variable_value.value:
(function execute(inputs, outputs) {

    var required = (inputs.required_documents || '')
        .split(',')
        .map(function(item) {
            return item.trim();
        })
        .filter(function(item) {
            return item !== '';
        });

    var submittedRaw = (inputs.submitted_documents || '')
        .split(',')
        .map(function(item) {
            return item.trim();
        })
        .filter(function(item) {
            return item !== '' && item !== 'None';
        });

    var submitted = [];

    submittedRaw.forEach(function(item) {

        // Step 4 returns:
        // Document Type (Status)
        // Example: Passport Copy (Verified)

        var docName = item.split(' (')[0].trim();

        if (docName && submitted.indexOf(docName) === -1) {
            submitted.push(docName);
        }
    });

    var submittedRequired = [];
    var missing = [];

    required.forEach(function(doc) {

        if (submitted.indexOf(doc) !== -1) {
            submittedRequired.push(doc);
        } else {
            missing.push(doc);
        }

    });

    outputs.required_list =
        required.join(', ') || 'None';

    outputs.submitted_list =
        submittedRequired.join(', ') || 'None';

    outputs.missing_list =
        missing.join(', ') || 'None — all required documents submitted';

})(inputs, outputs);

