sys_variable_value.value:
(function execute(inputs, outputs) {

    var caseRecord = inputs.visa_case_record;

    if (!caseRecord) {
        outputs.submitted_documents = 'None';
        return;
    }

    var caseSysId = caseRecord.getUniqueValue();
    var submittedDocs = [];

    // Build a lookup of raw choice value -> display label,
    // using the document_configuration table as the source of truth
    var labelLookup = {};
    var configGr = new GlideRecord('x_snc_visaguardi_0_document_configuration');
    configGr.query();
    while (configGr.next()) {
        var rawType = String(configGr.getValue('document_type')).toLowerCase();
        labelLookup[rawType] = configGr.getDisplayValue('document_type');
    }

    var gr = new GlideRecord('x_snc_visaguardi_0_visa_document');
    gr.addQuery('visa_case', caseSysId);
    gr.query();

    while (gr.next()) {
        var rawDocType = String(gr.getValue('document_type'));
        var displayDocType = gr.getDisplayValue('document_type');

        // Prefer the mapped label if the raw value matches a known config entry;
        // otherwise fall back to whatever display value the record already has
        var normalizedType = labelLookup[rawDocType.toLowerCase()] || displayDocType;

        var status = gr.getDisplayValue('document_status');

        if (normalizedType) {
            submittedDocs.push(normalizedType + ' (' + status + ')');
        }
    }

    outputs.submitted_documents = submittedDocs.join(', ') || 'None';

})(inputs, outputs);

