(function execute(inputs, outputs) {

    var response =
        'Required Documents:\n' +
        inputs.required_list +
        '\n\n' +
        'Submitted Documents:\n' +
        inputs.submitted_list +
        '\n\n' +
        'Missing Documents:\n' +
        inputs.missing_list;

    outputs.document_response = response;

})(inputs, outputs);

